import torch.nn as nn

class Module(nn.Module):
    def __init__(self):
        super(Module, self).__init__()
        self.fc1 = nn.Linear(300, 128)
        self.fc2 = nn.Linear(128, 300)

    def forward(self, x):
        x = torch.relu(self.fc1(x))
        x = self.fc2(x)
        return x

# Define the system
class System(nn.Module):
