from concurrent import futures
import grpc
import agent_pb2
import agent_pb2_grpc
import kafka

class AgentServicer(agent_pb2_grpc.AgentServiceServicer):
    def __init__(self):
        self.agents = {}
        self.kafka_producer = kafka.KafkaProducer(bootstrap_servers='localhost:9092')

    def RegisterAgent(self, request, context):
        agent_id = request.agent_id
        if agent_id not in self.agents:
            self.agents[agent_id] = True
            return agent_pb2.RegisterAgentResponse(success=True)
        else:
            context.set_code(grpc.StatusCode.ALREADY_EXISTS)
            context.set_details('Agent already registered.')
            return agent_pb2.RegisterAgentResponse(success=False)

    def UnregisterAgent(self, request, context):
        agent_id = request.agent_id
        if agent_id in self.agents:
            del self.agents[agent_id]
            return agent_pb2.UnregisterAgentResponse(success=True)
        else:
            context.set_code(grpc.StatusCode.NOT_FOUND)
            context.set_details('Agent not found.')
            return agent_pb2.UnregisterAgentResponse(success=False)

    def SendEvent(self, request, context):
        agent_id = request.agent_id
        event_data = request.event_data
        if agent_id in self.agents:
            self.kafka_producer.send('events_topic', key=agent_id.encode(), value=event_data.encode())
            return agent_pb2.SendEventResponse(success=True)
        else:
            context.set_code(grpc.StatusCode.NOT_FOUND)
            context.set_details('Agent not found.')
            return agent_pb2.SendEventResponse(success=False)

def serve():
    server = grpc.server(futures.ThreadPoolExecutor(max_workers=10))
    agent_pb2_grpc.add_AgentServiceServicer_to_server(AgentServicer(), server)
    server.add_insecure_port('[::]:50051')
    server.start()
    print("gRPC server started on port 50051")
    server.wait_for_termination()

if __name__ == '__main__':
    serve()
```

