    CidrBlock='10.0.0.0/16',
    TagSpecifications=[
        {
            'ResourceType': 'vpc',
            'Tags': [
                {
                    'Key': 'Name',
                    'Value': 'my-vpc'
                },
            ]
        },
    ]
)

# Create a public subnet
public_subnet = ec2.create_subnet(
    CidrBlock='10.0.1.0/24',
    VpcId=vpc['Vpc']['VpcId'],
    AvailabilityZone='us-west-2a',
    TagSpecifications=[
        {
            'ResourceType': 'subnet',
            'Tags': [
                {
                    'Key': 'Name',
                    'Value': 'public-subnet'
                },
            ]
        },
    ]
)

# Create a private subnet
private_subnet = ec2.create_subnet(
    CidrBlock='10.0.2.0/24',
    VpcId=vpc['Vpc']['VpcId'],
    AvailabilityZone='us-west-2a',
    TagSpecifications=[
        {
            'ResourceType': 'subnet',
            'Tags': [
                {
                    'Key': 'Name',
                    'Value': 'private-subnet'
                },
            ]
        },
    ]
)

# Create an Internet Gateway
internet_gateway = ec2.create_internet_gateway(
    TagSpecifications=[
        {
            'ResourceType': 'internet-gateway',
            'Tags': [
                {
                    'Key': 'Name',
                    'Value': 'my-internet-gateway'
                },
            ]
        },
    ]
)

# Attach the Internet Gateway to the VPC
ec2.attach_internet_gateway(
    InternetGatewayId=internet_gateway['InternetGateway']['InternetGatewayId'],
    VpcId=vpc['Vpc']['VpcId']
)

# Create a public route table
public_route_table = ec2.create_route_table(
    VpcId=vpc['Vpc']['VpcId'],
    TagSpecifications=[
        {
            'ResourceType': 'route-table',
            'Tags': [
                {
                    'Key': 'Name',
                    'Value': 'public-route-table'
                },
            ]
        },
    ]
)

# Create a private route table
private_route_table = ec2.create_route_table(
    VpcId=vpc['Vpc']['VpcId'],
    TagSpecifications=[
        {
            'ResourceType': 'route-table',
            'Tags': [
                {
                    'Key': 'Name',
                    'Value': 'private-route-table'
                },
            ]
        },
    ]
)

# Associate the public subnet with the public route table
ec2.associate_route_table(
    RouteTableId=public_route_table['RouteTable']['RouteTableId'],
    SubnetId=public_subnet['Subnet']['SubnetId']
)

# Associate the private subnet with the private route table
ec2.associate_route_table(
    RouteTableId=private_route_table['RouteTable']['RouteTableId'],
    SubnetId=private_subnet['Subnet']['SubnetId']
)

# Add a route to the public route table for internet access
ec2.create_route(
    DestinationCidrBlock='0.0.0.0/0',
    GatewayId=internet_gateway['InternetGateway']['InternetGatewayId'],
    RouteTableId=public_route_table['RouteTable']['RouteTableId']
)

# Create a NAT Gateway
nat_gateway = ec2.create_nat_gateway(
    AllocationId='eipalloc-xxxxxxxxxxxxx',  # Replace with your Elastic IP allocation ID
    SubnetId=public_subnet['Subnet']['SubnetId'],
    TagSpecifications=[
        {
            'ResourceType': 'natgateway',
            'Tags': [
                {
                    'Key': 'Name',
                    'Value': 'my-nat-gateway'
                },
            ]
        },
    ]
)

# Wait for the NAT Gateway to become available
while True:
    nat_gateway_status = ec2.describe_nat_gateways(NatGatewayIds=[nat_gateway['NatGateway']['NatGatewayId']])
    if nat_gateway_status['NatGateways'][0]['State'] == 'available':
        break

# Add a route to the private route table for internet access via the NAT Gateway
ec2.create_route(
    DestinationCidrBlock='0.0.0.0/0',
    NatGatewayId=nat_gateway['NatGateway']['NatGatewayId'],
    RouteTableId=private_route_table['RouteTable']['RouteTableId']
)

# Create a Network ACL for the public subnet
public_network_acl = ec2.create_network_acl(
    VpcId=vpc['Vpc']['VpcId'],
    TagSpecifications=[
        {
            'ResourceType': 'network-acl',
            'Tags': [
                {
                    'Key': 'Name',
                    'Value': 'public-network-acl'
                },
            ]
        },
    ]
)

# Create a Network ACL for the private subnet
private_network_acl = ec2.create_network_acl(
    VpcId=vpc['Vpc']['VpcId'],
    TagSpecifications=[
        {
            'ResourceType': 'network-acl',
            'Tags': [
                {
                    'Key': 'Name',
                    'Value': 'private-network-acl'
                },
            ]
        },
    ]
)

# Associate the public Network ACL with the public subnet
ec2.associate_network_acl(
    NetworkAclId=public_network_acl['NetworkAcl']['NetworkAclId'],
    SubnetId=public_subnet['Subnet']['SubnetId']
)

# Associate the private Network ACL with the private subnet
ec2.associate_network_acl(
    NetworkAclId=private_network_acl['NetworkAcl']['NetworkAclId'],
    SubnetId=private_subnet['Subnet']['SubnetId']
)

# Add ingress and egress rules to the public Network ACL
ec2.create_network_acl_entry(
    CidrBlock='0.0.0.0/0',
    Egress=False,
    Protocol='-1',
    RuleAction='allow',
    RuleNumber=100,
    NetworkAclId=public_network_acl['NetworkAcl']['NetworkAclId']
)

ec2.create_network_acl_entry(
    CidrBlock='0.0.0.0/0',
    Egress=True,
    Protocol='-1',
    RuleAction='allow',
    RuleNumber=100,
    NetworkAclId=public_network_acl['NetworkAcl']['NetworkAclId']
)

# Add ingress and egress rules to the private Network ACL
ec2.create_network_acl_entry(
    CidrBlock='0.0.0.0/0',
    Egress=False,
    Protocol='-1',
    RuleAction='allow',
    RuleNumber=100,
    NetworkAclId=private_network_acl['NetworkAcl']['NetworkAclId']
)

ec2.create_network_acl_entry(
    CidrBlock='0.0.0.0/0',
    Egress=True,
    Protocol='-1',
    RuleAction='allow',
    RuleNumber=100,
    NetworkAclId=private_network_acl['NetworkAcl']['NetworkAclId']
)

# Create a Security Group for the public subnet
public_security_group = ec2.create_security_group(
    Description='Public Security Group',
    GroupName='public-security-group',
    VpcId=vpc['Vpc']['VpcId'],
    TagSpecifications=[
        {
            'ResourceType': 'security-group',
            'Tags': [
                {
                    'Key': 'Name',
                    'Value': 'public-security-group'
                },
            ]
        },
    ]
)

# Create a Security Group for the private subnet
private_security_group = ec2.create_security_group(
    Description='Private Security Group',
    GroupName='private-security-group',
    VpcId=vpc['Vpc']['VpcId'],
    TagSpecifications=[
        {
            'ResourceType': 'security-group',
            'Tags': [
                {
                    'Key': 'Name',
                    'Value': 'private-security-group'
                },
            ]
        },
    ]
)

# Add inbound and outbound rules to the public Security Group
ec2.authorize_security_group_ingress(
    GroupId=public_security_group['GroupId'],
    IpPermissions=[
        {
            'IpProtocol': '-1',
            'FromPort': -1,
            'ToPort': -1,
            'IpRanges': [{'CidrIp': '0.0.0.0/0'}]
        },
    ]
)

ec2.authorize_security_group_egress(
    GroupId=public_security_group['GroupId'],
    IpPermissions=[
        {
            'IpProtocol': '-1',
            'FromPort': -1,
            'ToPort': -1,
            'IpRanges': [{'CidrIp': '0.0.0.0/0'}]
        },
    ]
)

# Add inbound and outbound rules to the private Security Group
ec2.authorize_security_group_ingress(
    GroupId=private_security_group['GroupId'],
    IpPermissions=[
        {
            'IpProtocol': '-1',
            'FromPort': -1,
            'ToPort': -1,
            'IpRanges': [{'CidrIp': '0.0.0.0/0'}]
        },
    ]
)

ec2.authorize_security_group_egress(
    GroupId=private_security_group['GroupId'],
    IpPermissions=[
        {
            'IpProtocol': '-1',
            'FromPort': -1,
            'ToPort': -1,
            'IpRanges': [{'CidrIp': '0.0.0.0/0'}]
        },
    ]
)

print("VPC setup complete.")
