                return response.json()  # Return the response content if needed
            else:
                logging.error(f"Communication with {microservice} failed with status code {response.status_code}")
                return None
        except requests.exceptions.RequestException as e:
            logging.warning(f"Request to {microservice} failed: {str(e)}")
            if attempt == retries:
                logging.error(f"Max retries reached for {microservice}")
                return None
            else:
                sleep_time = backoff_factor * (2 ** attempt)
                logging.info(f"Retrying {microservice} in {sleep_time:.2f} seconds")
                time.sleep(sleep_time)
                attempt += 1

# Handle the communication for each microservice
for microservice, url in microservices.items():
    handle_communication(microservice, url)
