    @patch('subprocess.run')
    def test_model_upload_process_failure(self, mock_run, mock_exists):
        # Mock the existence of the model file
        mock_exists.return_value = True

        # Mock the subprocess run to simulate a failed upload
        mock_run.side_effect = subprocess.CalledProcessError(returncode=1, cmd='upload_command')

        # Call the function that handles the model upload
        result = self.upload_model('model.pth')

        # Assert that the upload failed due to process failure
        self.assertFalse(result)

