### Improved Rollback Plan

```groovy
def rollbackPlan(buildNumber) {
    // Get the previous successful build
    def previousSuccessfulBuild = getPreviousSuccessfulBuild(buildNumber)

    if (!previousSuccessfulBuild) {
        echo "No previous successful build found. Aborting rollback."
        return
    }

    // Attempt to revert to the previous successful build
    def rollbackResult = revertToPreviousBuild(previousSuccessfulBuild)

    if (!rollbackResult) {
        echo "Rollback to previous build failed. Aborting further actions."
        return
    }

    // Restart the pipeline
    def restartResult = restartPipeline()

    if (!restartResult) {
        echo "Pipeline restart failed. Manual intervention required."
        return
    }

    echo "Rollback and pipeline restart completed successfully."
}

def getPreviousSuccessfulBuild(buildNumber) {
    def pipeline = Jenkins.instance.getItemByFullName('my-pipeline')
    def previousBuild = null

    for (int i = buildNumber - 1; i > 0; i--) {
        def candidateBuild = pipeline.getBuildByNumber(i)
        if (candidateBuild && candidateBuild.getResult().isBetterThan(hudson.model.Result.FAILURE)) {
            previousBuild = candidateBuild
            break
        }
    }

    return previousBuild
}

def revertToPreviousBuild(previousBuild) {
    try {
        // Perform the actual rollback steps
        // Example: checkout previous commit, rebuild, redeploy
        echo "Reverting to build ${previousBuild.getNumber()}"

        // Example steps
        checkout([$class: 'GitSCM', branches: [[name: "refs/tags/${previousBuild.getNumber()}"]]])
        sh 'make build'
        sh 'make deploy'

        return true
    } catch (Exception e) {
        echo "Rollback to previous build failed: ${e}"
        return false
    }
}

def restartPipeline() {
