                        currentBuild.result = 'FAILURE'
                        error "Deployment failed: ${e}"
                    }
                }
            }
        }
        stage('Rollout Feature') {
            steps {
                script {
                    try {
                        rollout_feature(FEATURE_NAME)
                    } catch (Exception e) {
                        echo "Feature rollout failed: ${e}"
                        currentBuild.result = 'FAILURE'
                        error "Feature rollout failed: ${e}"
                    }
                }
            }
        }
        stage('Verify Feature') {
            steps {
                script {
                    try {
                        sh 'make verify-feature'
                    } catch (Exception e) {
                        echo "Feature verification failed: ${e}"
                        currentBuild.result = 'FAILURE'
                        error "Feature verification failed: ${e}"
                    }
                }
            }
        }
        stage('Rollback Feature') {
            when {
                expression { currentBuild.result == 'FAILURE' }
            }
            steps {
                script {
                    try {
                        rollback_feature(FEATURE_NAME)
                    } catch (Exception e) {
                        echo "Feature rollback failed: ${e}"
                        currentBuild.result = 'FAILURE'
                        error "Feature rollback failed: ${e}"
                    }
                }
            }
        }
    }
    post {
        always {
            // Clean up workspace
            cleanWs()
        }
        success {
            echo 'Feature rollout successful'
        }
        failure {
            echo 'Feature rollout failed'
        }
    }
}

