```python
import grpc
from concurrent import futures
from agent_service_pb2 import RegisterAgentRequest, RegisterAgentResponse
from agent_service_pb2_grpc import AgentServiceServicer, add_AgentServiceServicer_to_server

class AgentService(AgentServiceServicer):
    def RegisterAgent(self, request, context):
        # Implement registration logic
        print(f"Received agent: {request.id}, {request.name}")
        return RegisterAgentResponse(message="Agent registered successfully")

def serve():
    server = grpc.server(futures.ThreadPoolExecutor(max_workers=10))
    add_AgentServiceServicer_to_server(AgentService(), server)
    server.add_insecure_port("[::]:50051")
    server.start()
    server.wait_for_termination()

if __name__ == "__main__":
    serve()
```

